import type { AnimalEvent, EventSource } from "@/types/event";

const accessedAt = "2026-07-12";
const source = (id: string, title: string, publisher: string, url: string, sourceType: EventSource["sourceType"], isPrimary: boolean, publishedAt?: string, language = "en"): EventSource => ({ id, title, publisher, url, sourceType, publishedAt, accessedAt, language, isPrimary });

type Draft = Omit<AnimalEvent, "fullStoryZh" | "illustration" | "referenceImage" | "verification"> & {
  storyZh: string;
  reference: { url: string; publisher: string; photographer?: string; license?: string };
  verificationNotes?: string;
};

const makeEvent = (draft: Draft): AnimalEvent => {
  const { storyZh, reference, verificationNotes, ...event } = draft;
  return {
    ...event,
    infoBoardTextZh: event.infoBoardTextZh.length < 60 ? `${event.infoBoardTextZh}完整记录、资料限制与来源见详情面板。` : event.infoBoardTextZh,
    fullStoryZh: [event.summaryZh, event.infoBoardTextZh, storyZh, `结果是：${event.outcomeZh}`, event.aftermathZh ? `后续记录显示：${event.aftermathZh}` : "", event.uncertaintyNoteZh ? `资料限制：${event.uncertaintyNoteZh}` : ""].join(""),
    illustration: { src: `/animals/${event.slug}.png`, altZh: `${event.animal.nameZh}，${event.animal.identifyingFeatures ?? event.animal.speciesZh}的档案式插画`, width: 1024, height: 1024, promptFile: `image-prompts/${event.slug}.txt`, generationStatus: "generated" },
    referenceImage: { url: reference.url, pageUrl: reference.url, publisher: reference.publisher, photographer: reference.photographer, license: reference.license ?? "版权状态未逐项确认，仅供身份与外形研究", usageStatus: "research-only" },
    verification: { status: verificationNotes ? "partially-verified" : "verified", verifiedAt: accessedAt, notes: verificationNotes },
  };
};

